#app [data-testid="drawer-middle"] [data-testid="empty-state-drawer"],
#app [data-testid="drawer-middle"] [data-testid="empty-state-drawer"] > .x1n2onr6.x1r8uery > .x10l6tqk.x1vjfegm,
